  if (unterminated >= 0) {
    const hidden = new RegExp(`<${name}\\b`, 'g');
    hidden.lastIndex = unterminated;
    for (let m; (m = hidden.exec(xml)); ) {
      elements.push({ attrs: null, inner: null, line: lineAt(m.index), problem: 'inside an unterminated comment or declaration' });
    }
