// Quote-aware split into command segments (newline, ;, &&, ||, |, &, grouping) and tokens.
function tokenize(command) {
  const text = command.replace(/\\\r?\n|`\r?\n/g, ' ');
  const segments = [];
  let tokens = [];
  let current = '';
  let started = false;
  let quote = null;
  const endToken = () => {
    if (started) tokens.push(current);
    current = '';
    started = false;
  };
  const endSegment = () => {
    endToken();
    if (tokens.length > 0) segments.push(tokens);
    tokens = [];
  };
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    if (quote) {
      if (c === quote) quote = null;
      else if (quote === '"' && (c === '\\' || c === '`') && (text[i + 1] === '"' || text[i + 1] === c)) current += text[(i += 1)];
      else current += c;
    } else if (c === '"' || c === "'") {
      quote = c;
      started = true;
    } else if (c === '&' && text[i - 1] === '>') {
      current += c; // 2>&1 is a redirection, not a separator
    } else if (SEGMENT_BREAKS.has(c)) {
      endSegment();
    } else if (/\s/.test(c)) {
      endToken();
    } else {
      current += c;
      started = true;
    }
  }
  endSegment();
  return segments;

