    }
    for (const f of m.facets.filter((x) => x.file.endsWith('.json'))) {
      const body = readText(path.join(root, f.file), f.file);
      for (const seg of frameSegments) if (new RegExp(`\\*\\.${esc(seg)}\\b`).test(body)) evidence.push(`${f.file}: *.${seg}`);
