    if (a.rel === 'CLAUDE.md' || !a.rel.endsWith('.md')) continue;
    if (/^@[\w.\/-]+\.md\s*$/m.test(a.body)) out.push(lib.finding(ERR, a.rel, 'only CLAUDE.md may contain @ imports'));
